// ─── File: PrivateClassDemo.java ───
// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.privateclass;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class PrivateClassDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya",  new BigDecimal("250000"));

        TransferService service = new TransferService();
        boolean ok = service.transferWithRetry(rajesh, priya, new BigDecimal("50000"), 3);
        log.info(() -> "Transfer success=" + ok + " rajesh=Rs." + rajesh.getBalance()
                + " priya=Rs." + priya.getBalance());

        // NOTE: the following would NOT compile — top-level class cannot be private:
        // private class TopLevelHelper {}   // error: modifier private not allowed here
        // That is why TransferAttempt lives as a PRIVATE NESTED class inside TransferService.
    }
}

// top-level class: only 'public' or package-private (default) is legal here.
// 'private class Account' here would be a COMPILE ERROR.
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId = id; holderName = name; balance = bal; }
    void debit(BigDecimal a)  { balance = balance.subtract(a); }
    void credit(BigDecimal a) { balance = balance.add(a); }
    BigDecimal getBalance() { return balance; }
    String getAccountId() { return accountId; }
}

// top-level: package-private (no modifier). Cannot be 'private'.
class TransferService {
    private static final Logger log = Logger.getLogger("BankLog");

    // PRIVATE NESTED CLASS: legal because it is a MEMBER of TransferService.
    // Visible ONLY inside TransferService. No other class can name this type.
    private static class TransferAttempt {
        private final BigDecimal amount;
        private int retries;
        private TransferAttempt(BigDecimal amount) { this.amount = amount; }
    }

    boolean transferWithRetry(Account from, Account to, BigDecimal amount, int maxRetries) {
        TransferAttempt attempt = new TransferAttempt(amount); // only usable here
        while (attempt.retries < maxRetries) {
            try {
                if (from.getBalance().compareTo(attempt.amount) < 0) {
                    throw new IllegalStateException("insufficient funds");
                }
                from.debit(attempt.amount);
                to.credit(attempt.amount);
                log.info(() -> "transfer succeeded on attempt " + (attempt.retries + 1));
                return true;
            } catch (RuntimeException ex) {
                attempt.retries++;
                int shown = attempt.retries;
                log.warning(() -> "attempt " + shown + " failed: " + ex.getMessage());
            }
        }
        log.severe(() -> "transfer failed after " + maxRetries + " attempts");
        return false;
    }
}
